#!/usr/bin/env python3
"""Publish the `module load ood/<app>/<version>` modules for the app images.

Reads the image tables of the apps (template/script.sh.erb, the same ones the
OnDemand apps use), then writes to DEST (default /ijc/PUBLIC/DATA/images/ood,
through SSH_HOST since the workstation does not mount /ijc):

  modulefiles/ood/jupyter/<version>.lua, .../rstudio/<version>.lua  (+ .modulerc.lua: default = newest)
  modulefiles/ood/conda.lua      conda-forge conda for the envs in ~/.conda/envs
  bin/ood-exec, ood-run, ood-shell; bin/<app>/python, Rscript, ... (run in the image)
  lib/ood_slurm.sh               the cluster's Slurm inside the images (from .github/ood-checks)
  R/Rprofile.site, R/ood.R       the RStudio app's R profile and helpers
  catalog.tsv, README.md

Files it does not generate (lib/glibc2.17/libmunge.so.2) are left alone;
modulefiles and command wrappers for images no longer offered are removed.

  publish.py [--repo DIR] [--dest DIR] [--ssh-host HOST] [--dry-run]
"""
import argparse
import os
import re
import shlex
import subprocess
import sys
import tempfile
from pathlib import Path

HERE = Path(__file__).resolve().parent
GPU_PARTITION = "test-gpu"

APPS = {
    # app dir, module name, commands run in the image, title
    "jupyter": ("jupyter", ["python", "python3", "pip", "pip3", "jupyter", "ipython", "conda", "uv",
                            "cellranger", "cellranger-arc"], "Jupyter Lab image"),
    "rstudio_bioconductor_321": ("rstudio", ["R", "Rscript"], "RStudio / Bioconductor image"),
}


def image_table(app_dir):
    """[(label, image, workdir_or_None)] in table order, and {alias: label}."""
    text = (app_dir / "template/script.sh.erb").read_text()
    rows = []
    for m in re.finditer(r'^    "([^"]+)" => (?:"([^"]+)"|\["([^"]+)", "([^"]+)"\]),$', text, re.M):
        rows.append((m.group(1), m.group(2) or m.group(3), m.group(4)))
    am = re.search(r"^  aliases = \{(.*)\}$", text, re.M)
    aliases = dict(re.findall(r'"([^"]+)" => "([^"]+)"', am.group(1))) if am else {}
    return rows, aliases


def version_of(label, image, aliases):
    """The module version: the image file's version (jupyter-cellranger_2026.11.2.sif ->
    2026.11.2, bioconductor_3.24.sif -> 3.24), else the short value saved sessions used
    (numeric ones first: "2026.02.1" before "cuda13"), else the Bioconductor version."""
    m = re.search(r"_(\d+(?:\.\d+)+)\.sif$", image)
    if m:
        return m.group(1)
    short = [a for a, l in aliases.items() if l == label]
    short.sort(key=lambda a: (not re.fullmatch(r"[\d.]+", a), a))
    if short:
        return short[0]
    m = re.search(r"Bioconductor (\d+\.\d+)", label)
    return m.group(1) if m else re.sub(r"[^A-Za-z0-9.]+", "-", label).strip("-").lower()


def lua(s):
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


def modulefile(dest, mod, app_key, cmds, title, label, image, workdir, version, default):
    bioc = re.search(r"Bioconductor (\d+\.\d+)", label)
    examples = {
        "jupyter": f"""  python analysis.py                   # in the image (inside a Slurm job)
  ood-run -c 8 --mem 32G -t 4:00:00 -- python analysis.py
  ood-run --gpu -c 4 --mem 32G -- python train.py
  OOD_CONDA_ENV=myenv python x.py      # a conda env of ~/.conda/envs instead of the image's
  ood-shell -c 4 --mem 16G             # interactive shell in the image""",
        "rstudio": f"""  Rscript analysis.R                   # in the image (inside a Slurm job), with the
                                       # RStudio app's library for this version
  ood-run -c 8 --mem 32G -t 4:00:00 -- Rscript analysis.R
  ood-run -c 16 -- Rscript -e 'ood_reinstall_packages(ask = FALSE)'
  ood-shell -c 4 --mem 16G             # interactive shell in the image""",
    }[mod]
    lines = [
        f"-- Generated by .github/ood-modules/publish.py from the onDemand repo; do not edit here.",
        f"local root = {lua(dest)}",
        f'whatis("Name: ood/{mod}")',
        f'whatis("Version: {version}")',
        f"whatis({lua('Description: ' + title + ': ' + label)})",
        "help([[",
        f"{title} {version}{' (default)' if default else ''}: {label}",
        f"Image: {image}",
        "",
        f"Runs {', '.join(cmds)} inside the image the OnDemand app uses, set up the same way.",
        "Containers do not run on the login node: use these inside a Slurm job, or:",
        "",
        examples,
        "",
        f"More: {dest}/README.md",
        "]])",
        'family("ood")',
        'setenv("OOD_ROOT", root)',
        f'setenv("OOD_APP", {lua(mod)})',
        f'setenv("OOD_IMAGE", {lua(image)})',
        f'setenv("OOD_IMAGE_LABEL", {lua(label)})',
        'setenv("OOD_MODULE", myModuleFullName())',
        f'setenv("OOD_GPU_PARTITION", {lua(GPU_PARTITION)})',
    ]
    if workdir:
        lines.append(f'setenv("OOD_R_WORKDIR", {lua(workdir)})')
    if bioc:
        lines.append(f'setenv("OOD_BIOC_VERSION", {lua(bioc.group(1))})')
    lines += ['prepend_path("PATH", pathJoin(root, "bin"))',
              f'prepend_path("PATH", pathJoin(root, "bin", {lua(mod)}))', ""]
    return "\n".join(lines)


CONDA_MODULE = """-- Generated by .github/ood-modules/publish.py; do not edit here.
-- conda for the environments in ~/.conda/envs (the ones the OnDemand apps use), from conda-forge.
local root = {root}
whatis("Name: ood/conda")
whatis("Description: conda (conda-forge) for the environments in ~/.conda/envs, the same ones the OnDemand apps use")
help([[
conda for the environments the OnDemand apps use (~/.conda/envs), from conda-forge.

  module load ood/conda
  conda activate myenv          # an env made in Jupyter, VS Code or here
  conda create -n myenv python=3.12 ipykernel   # appears as a kernel in Jupyter

Before running an env's programs in a job, clear libraries other modules set:
  module purge; module load ood/conda; conda activate myenv
]])
depends_on("Miniconda3/24.7.1-0")
setenv("CONDARC", pathJoin(root, "conda", "condarc"))
setenv("CONDA_ENVS_PATH", pathJoin(os.getenv("HOME"), ".conda", "envs") .. ":" .. pathJoin(os.getenv("HOME"), "jupyterlab_ood", "conda-envs"))
if (mode() == "load") then
  execute{{cmd = 'source "$EBROOTMINICONDA3/etc/profile.d/conda.sh"', modeA = {{"load"}}}}
end
"""

CONDARC = """# conda settings for `module load ood/conda` (CONDARC): conda-forge only,
# like conda inside the OnDemand Jupyter images.
channels:
  - conda-forge
channel_priority: strict
auto_activate_base: false
"""


def shim(cmd):
    return f'#!/bin/sh\n# Generated by publish.py: {cmd} in the loaded ood module\'s image.\nexec "${{OOD_ROOT:-$(dirname "$0")/../..}}/bin/ood-exec" {shlex.quote(cmd)} "$@"\n'


def build(repo, dest, out):
    catalog = ["# module\tapp\timage\tlabel"]
    files = {}
    for app_dir_name, (mod, cmds, title) in APPS.items():
        rows, aliases = image_table(repo / app_dir_name)
        seen = set()
        for i, (label, image, workdir) in enumerate(rows):
            v = version_of(label, image, aliases)
            if v in seen:
                raise SystemExit(f"{app_dir_name}: two images map to version {v}")
            seen.add(v)
            files[f"modulefiles/ood/{mod}/{v}.lua"] = modulefile(dest, mod, app_dir_name, cmds, title, label, image,
                                                                 workdir, v, i == 0)
            catalog.append(f"ood/{mod}/{v}\t{mod}\t{image}\t{label}")
        first = version_of(*rows[0][:2], aliases)
        files[f"modulefiles/ood/{mod}/.modulerc.lua"] = f'module_version("ood/{mod}/{first}", "default")\n'
        for c in cmds:
            files[f"bin/{mod}/{c}"] = shim(c)
    files["modulefiles/ood/conda.lua"] = CONDA_MODULE.format(root=lua(dest))
    files["conda/condarc"] = CONDARC
    for f in ("ood-exec", "ood-run", "ood-shell"):
        files[f"bin/{f}"] = (HERE / f).read_text()
    files["lib/ood_slurm.sh"] = (repo / ".github/ood-checks/ood_slurm.sh").read_text()
    files["R/Rprofile.site"] = (repo / "rstudio_bioconductor_321/template/ood-R/Rprofile.site").read_text()
    files["R/ood.R"] = (repo / "rstudio_bioconductor_321/template/ood-R/ood.R").read_text()
    files["catalog.tsv"] = "\n".join(catalog) + "\n"
    files["README.md"] = (HERE / "README.md").read_text().replace("@DEST@", dest)
    for rel, text in files.items():
        p = out / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(text)
        if rel.startswith("bin/"):
            p.chmod(0o755)
    return sorted(files), catalog


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--repo", default=str(HERE.parent.parent))
    ap.add_argument("--dest", default="/ijc/PUBLIC/DATA/images/ood")
    ap.add_argument("--ssh-host", default="minastirith")
    ap.add_argument("--dry-run", action="store_true")
    a = ap.parse_args()
    with tempfile.TemporaryDirectory(prefix="ood-modules-") as tmp:
        out = Path(tmp) / "ood"
        names, catalog = build(Path(a.repo), a.dest, out)
        print("\n".join(catalog[1:]))
        if a.dry_run:
            print(f"(dry run) would publish {len(names)} files to {a.ssh_host}:{a.dest}")
            return 0
        # Upload next to DEST, then move each file into place (the login node
        # cannot run mv/cp; python can) and drop generated files that are gone.
        stage = f"{a.dest}.upload-{os.getpid()}"
        subprocess.run(["scp", "-q", "-r", str(out), f"{a.ssh_host}:{stage}"], check=True)
        py = f"""
import os, shutil
dest, stage, names = {a.dest!r}, {stage!r}, {names!r}
for rel in names:
    os.makedirs(os.path.dirname(os.path.join(dest, rel)), exist_ok=True)
    os.replace(os.path.join(stage, rel), os.path.join(dest, rel))
for top in ("modulefiles/ood", "bin"):
    for d, _, fs in os.walk(os.path.join(dest, top)):
        for f in fs:
            rel = os.path.relpath(os.path.join(d, f), dest)
            if rel not in names:
                os.remove(os.path.join(dest, rel)); print("removed", rel)
shutil.rmtree(stage, ignore_errors=True)
print("published", len(names), "files to", dest)
"""
        r = subprocess.run(["ssh", "-o", "BatchMode=yes", a.ssh_host, "python3", "-"], input=py, text=True,
                           capture_output=True)
        print(r.stdout.strip())
        if r.returncode:
            print(r.stderr, file=sys.stderr)
            return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
